package glitch

import data.glitch_lib

weak_pattern := "(?i)\\b(DES|3DES|RC4|Blowfish|AES[-_ ]?128|ECB|MD5|SHA1|SHA-1|SHA_1|SHA\\b(?!256|384|512)|SSLv2|SSLv3|TLS[-_ ]?1\\.0|TLS[-_ ]?1\\.1)\\b"

# Helper to check if a string matches the weak pattern
check_weak_string(value, pattern) {
    value.ir_type == "String"
    regex.match(pattern, value.value)
}

# Helper to check function call arguments recursively
check_function_call_args(args, pattern) {
    some arg in args
    check_expr_weak(arg, pattern)
}

# Helper to check expressions (String, Access, Sum, FunctionCall, etc.) for weak pattern
check_expr_weak(expr, pattern) {
    expr.ir_type == "String"
    regex.match(pattern, expr.value)
} else {
    expr.ir_type == "Access"
    check_expr_weak(expr.left, pattern) or check_expr_weak(expr.right, pattern)
} else {
    expr.ir_type == "Sum"
    check_expr_weak(expr.left, pattern) or check_expr_weak(expr.right, pattern)
} else {
    expr.ir_type == "FunctionCall"
    check_function_call_args(expr.args, pattern)
} else {
    expr.ir_type == "VariableReference"
    check_weak_string(expr, pattern)
}

# Rule for FunctionCall arguments (e.g., Ansible hash filter with 'sha1')
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    walk(parent, [_, node])
    node.ir_type == "FunctionCall"
    check_function_call_args(node.args, weak_pattern)

    result := {
        "type": "sec_weak_crypt",
        "element": node,
        "path": parent.path,
        "description": "Use of weak cryptographic algorithm in function arguments - Avoid using broken or risky cryptographic algorithms. (CWE-327)"
    }
}

# Rule for Attribute values (e.g., Ansible encrypt attribute with 'md5_crypt')
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
