        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of weak cryptographic algorithm in attribute value - Avoid using broken or risky cryptographic algorithms. (CWE-327)"
    }
}

# Rule for Variable values (e.g., Chef cipher_suites with 'TLS_RSA_WITH_AES_128_CBC_SHA')
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
